      "\nALTER TABLE \"campaign_rewards\" ADD CONSTRAINT \"campaign_rewards_account_id_accounts_id_fk\" FOREIGN KEY (\"account_id\") REFERENCES \"public\".\"accounts\"(\"id\") ON DELETE no action ON UPDATE no action;"
